import json
from collections import deque

T = [[1, 2, 3, 0], [1, 0, 2, 3]]
U = [[3, 2, 0, 1], [2, 1, 0, 3]]
d = 4
V = d + 5
F = [None] * d
conflict = False
mode = 'idle'
reg = 0
assignments = 0


def close(i, j):
    global conflict, assignments
    if conflict:
        return
    queue = deque([(i, j)])
    while queue and not conflict:
        x, y = queue.popleft()
        if F[x] is None:
            F[x] = y
            assignments += 1
            for a in range(2):
                queue.append((T[a][x], U[a][y]))
        elif F[x] != y:
            conflict = True
            queue.clear()


def feed(token):
    global mode, reg
    numeric = isinstance(token, int) and 0 <= token < d
    if mode == 'idle':
        if token == 'D':
            mode = 'demo_source'
        elif token == 'Q':
            mode = 'query_source'
    elif mode == 'demo_source' and numeric:
        reg = token
        mode = 'demo_target'
    elif mode == 'demo_target' and numeric:
        close(reg, token)
        mode = 'idle'
    elif mode == 'query_source' and numeric:
        reg = token
        mode = 'word'
    elif mode == 'word' and token in ('L', 'R'):
        reg = T[0 if token == 'L' else 1][reg]
    elif mode == 'word' and token == '?':
        mode = 'answer'
    elif mode == 'answer' and numeric:
        mode = 'idle'
    else:
        mode = 'idle'
    if mode != 'answer':
        return [1.0 / V] * V
    if conflict or F[reg] is None:
        return [1.0 / d] * d + [0.0] * 5
    p = [0.0] * V
    p[F[reg]] = 1.0
    return p


for token in ['D', 0, 2]:
    feed(token)
learned = list(F)
answers = []
for word in [('L', 'R'), ('R', 'L')]:
    feed('Q')
    feed(0)
    for operation in word:
        feed(operation)
    p = feed('?')
    answer = p.index(1.0)
    answers.append(answer)
    feed(answer)
for token in ['D', 2, 0]:
    feed(token)
for token in ['Q', 1, '?']:
    p = feed(token)
result = {'learned_map': learned, 'assignments': assignments, 'LR_answer': answers[0], 'RL_answer': answers[1], 'conflict': conflict, 'fallback_distribution': [round(x, 4) for x in p]}
print(json.dumps(result, sort_keys=True))
